"use strict";(self.webpackChunkrithmia=self.webpackChunkrithmia||[]).push([["4187"],{1210(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>c,frontMatter:()=>r,contentTitle:()=>s,toc:()=>l,assets:()=>h});var i=JSON.parse('{"id":"Setting/History/legend-of-containment","title":"Legend of Containment (~8,500PD)","description":"In a time before ages shortly after The Evacuation of the Yith, during the Age of Creation where each of the 10 original deities where terraforming a planet of their own, coming into their power -- The Unspeakable One awoke. Still groggy this being stretched in the early morning of the universe and its violet light began to spread across all realms of reality. In spite of its nature as a facet of reality the light stopped in a large region of the material plane. The 10 prime deities were holding back the purple light from their new creations, the Rithmiasphere. Agitated by this an idea sprang from The Unspeakable and its first spawn was born. The idea was a creature that could eradicate anything in its path and thus Yith\'Zizctal, The Consumer was born. The immovable object was about to meet an unstoppable force and a winner would be decided as Yith\'Zizctal rush at near the speed of light at the Rithmiasphere.","source":"@site/docs/Setting/History/legend-of-containment.md","sourceDirName":"Setting/History","slug":"/Setting/History/legend-of-containment","permalink":"/Rithmia/docs/Setting/History/legend-of-containment","draft":false,"unlisted":false,"editUrl":"https://github.com/TravisH18/Rithmia/tree/main/docs/docs/Setting/History/legend-of-containment.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3},"sidebar":"settingSidebar","previous":{"title":"Age of Creation (12,000BD - 8,500BD)","permalink":"/Rithmia/docs/Setting/History/age-of-creation"},"next":{"title":"The First Flood (~8,500PD - 8,400PD)","permalink":"/Rithmia/docs/Setting/History/the-first-flood"}}'),n=a(4848),o=a(8453);let r={sidebar_position:3},s="Legend of Containment (~8,500PD)",h={},l=[{value:"Lasting effects on the deities.",id:"lasting-effects-on-the-deities",level:2}];function d(e){let t={h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"legend-of-containment-8500pd",children:"Legend of Containment (~8,500PD)"})}),"\n",(0,n.jsx)(t.p,{children:"In a time before ages shortly after The Evacuation of the Yith, during the Age of Creation where each of the 10 original deities where terraforming a planet of their own, coming into their power -- The Unspeakable One awoke. Still groggy this being stretched in the early morning of the universe and its violet light began to spread across all realms of reality. In spite of its nature as a facet of reality the light stopped in a large region of the material plane. The 10 prime deities were holding back the purple light from their new creations, the Rithmiasphere. Agitated by this an idea sprang from The Unspeakable and its first spawn was born. The idea was a creature that could eradicate anything in its path and thus Yith'Zizctal, The Consumer was born. The immovable object was about to meet an unstoppable force and a winner would be decided as Yith'Zizctal rush at near the speed of light at the Rithmiasphere."}),"\n",(0,n.jsx)(t.p,{children:"Yith\u2019Zizctal has the unique ability to consume a being and wipe all trace of it from existence. Their name may not be said and mention of them is wiped from memory of any mortal being and even in books that make reference to them have the name erased from its pages. This is because all mentions of them are transported to the demiplane that occupies the interior of The Consumer's stomach called Hunger's Void."}),"\n",(0,n.jsx)(t.p,{children:"The creator gods of the Rithmiasphere were put on the defensive. They recognized the danger they were in as the great old one dashed towards their solar system. A plan had to be made to slay the creature."}),"\n",(0,n.jsx)(t.p,{children:"To begin with the plan Ados and Caldor forged 6 mighty pillars of black stone. These were given to Zeisis, The Reaper who then acupunctured them into Rithmia's surface which Gaia volunteered to give up in order to create a prison for the creature. They planned to seal the creature inside the planet for all eternity. The rest of the prime deities fought Yith'Zizctal until the great old one was able to consume ___ and ___ then shattered the crystal sphere, a metaphysical barrier surrounding the solar system, and carried on with the fight. Xinthris then was forced to abandon the fight and hold together a tear in reality caused by two deities being erased from existence. This fractured Xinthris' mind as they peered into the realm beyond, the Outer realm, causing the once calm cool collected deity of magic into their now chaotic state."}),"\n",(0,n.jsx)(t.p,{children:"Gharian and Caldor fought side by side while Asmodeus engineered an eternally binding contract to seal this foul beast away. Gaia, known as The Allmother until this moment, split herself into two parts (The Earth and The Hypogean) and ripped the Mouth of Rithmia open. Ados healed Xinthris mind best they could and in a joint effort these two crafted a demiplanar prison the size of the core of Rithmia using a material Caldor created. Xinthris meticulously crafted an abjuration to contain this mighty creature who's stomach is also a demiplane. Once weakened by the two greatest warriors of the prime deities, Gharian and Caldor who both suffered intense, everlasting wounds Zeisis attempted to rip The Consumer's soul from its body. To their horror there was no one soul but an amalgamation of smaller pieces that constantly grew and replaced themselves healing and growing The Consumer every minute. These gigantic insectoid cells of Yith'Zizctal later became known as the scourge and in his foolishness Zeisis scattered The Scourge across the surface of Rithmia. However, this did greatly weaken the creature and over the Mouth of The World Janus dealt the final banishing judgment to Yith'Zizctal. The demplanar prison was then locked by Asmodeus who has kept the key at his side ever since."}),"\n",(0,n.jsx)(t.p,{children:"Now around the world 6 ancient pillars of black stone that pierce 500ft in the air serve as the material anchor for the planar forcecage preventing Yith'Zizctal from escaping their prison."}),"\n",(0,n.jsx)(t.p,{children:"Once the great purple light of The Unspeakable One, an outer god of pure entropy, literally the purple light of the visible light spectrum hit a barrier which it could not breach it became upset. Spawning from this anger was his first creation that walked separate from him. Later known as Yith'Zizctal, The Consumer this great old one ripped through space at an ungodly speed hurling itself towards the Rithmiasphere. Ten deities stood their ground against this fowl beast and from a certain perspective, they lost. The beast was not slain, just trapped in one of the planets of their new precious solar system."}),"\n",(0,n.jsx)(t.p,{children:"The Consumer has the ability to swallow all aspects of anything, meaning its history was wiped away as well as its physical essence. Two deities were entirely consumed. Only 8 deities were left standing, 5 of which were seriously injured. Gaia split herself into two: The Earth, and The Undergrowth. Only the deities of Law: Asmodeus, Janus, and Ados suffered no long term damage from this battle. Gharian took the largest damage and now sits on a throne, like a mixture of the statue of zeus and the emperor of man, using all of his remaining power to keep the sun lit and happiness and joy available to mortals. This battle and sealing is known as the Legend of Containment"}),"\n",(0,n.jsx)(t.h2,{id:"lasting-effects-on-the-deities",children:"Lasting effects on the deities."}),"\n",(0,n.jsx)(t.p,{children:"Gaia: Split into two weakened aspects The Earth and the Hypogean"}),"\n",(0,n.jsx)(t.p,{children:"Caldor: Lost one hand and shattered his original axe. Pieces of which are discovered by mortals as a great Godmetal on the planet."}),"\n",(0,n.jsx)(t.p,{children:"Gharian: Allmight like injury he is nearly paralyzed. Barely able to keep the light of the dawn bright enough he sits on a golden throne which keeps him alive much like the emperor of mankind in 40K."}),"\n",(0,n.jsx)(t.p,{children:"Xintrhis: Mind fractured while holding together a tear in reality. Possibly had an encounter with The Unspeakable One or one of the other elder gods of the outer realm. This pushed them to create mortals with freewill that could grow in strength and possibly defend this realm if The Consumer were to ever break free of its prison"}),"\n",(0,n.jsx)(t.p,{children:"Zeisis: In an attempt to rip The Consumer's soul from his body he help spread The Scourge across the surface of all the planets in the Rithmia sphere. Zeisis had to use an immense amount of their power to create all the psychopomps and while they weren't fractured like Gaia they were personally now bound to the River of souls and their lesser servants had to do the bidding of the once omnipresent Reaper"})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},8453(e,t,a){a.d(t,{R:()=>r,x:()=>s});var i=a(6540);let n={},o=i.createContext(n);function r(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);